using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Unity.AI.Navigation;using Object=UnityEngine.Object;
namespace DeliveryService.Mok.Editor{
[InitializeOnLoad] public static class PrisonExteriorSetup{
static PrisonExteriorSetup(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("Temp/PrisonExterior"))return;var a=File.ReadAllText("Temp/PrisonExterior").Trim();File.Delete("Temp/PrisonExterior");try{if(a=="build")Build();else if(a=="approach")Approach();else if(a=="sweep")Sweep();else if(a=="audit")Audit();else if(a=="polish")Polish();else Survey();}catch(Exception e){File.WriteAllText("Logs/Prison-exterior.txt",e.ToString());}}
const string Folder="Assets/DeliveryPrisonChapter/Escape/Exterior/";
static Material Mat(string name,Color color){var path=Folder+name+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(mat,path);}mat.color=color;return mat;}
static Transform At(string name,Transform parent,Vector3 p){var t=new GameObject(name).transform;t.SetParent(parent);t.position=p;return t;}
static GameObject Box(string name,Transform parent,Vector3 p,Vector3 size,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent);g.transform.position=p;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;g.isStatic=true;return g;}
static GameObject Prop(string file,Transform parent,Vector3 p,float height,float yaw){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Synty/PolygonGeneric/Prefabs/Environment/"+file+".prefab");if(!prefab)throw new Exception(file);var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab,parent.gameObject.scene);g.transform.SetParent(parent);g.transform.rotation=Quaternion.Euler(0,yaw,0);var rs=g.GetComponentsInChildren<Renderer>();Bounds b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);g.transform.localScale*=height/b.size.y;b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);g.transform.position+=p-new Vector3(b.center.x,b.min.y,b.center.z);g.isStatic=true;return g;}
static void Build(){
var m=Object.FindFirstObjectByType<PrisonTransportEscape>();var scene=m.gameObject.scene;if(scene.name!="PrisonChapter")throw new Exception("Prison only");
if(!EditorSceneManager.SaveScene(scene,"Logs/Prison-before-exterior-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true))throw new Exception("Backup failed");
if(m.road)throw new Exception("Exterior already installed");Directory.CreateDirectory(Folder);AssetDatabase.Refresh();
var root=At("31_호송 출발 골목과 교도소 밖 숲길",null,Vector3.zero);UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(root.gameObject,scene);var routeRoot=At("호송차량 실제 이동 경로",root,Vector3.zero);m.road=routeRoot.gameObject.AddComponent<PrisonTransportRoute>();
var pts=new[]{new Vector3(-48,.15f,-20),new Vector3(-48,.15f,-10),new Vector3(-48,.15f,8),new Vector3(-48,.15f,24),new Vector3(-46,.15f,39),new Vector3(-39,.15f,46),new Vector3(-25,.15f,47),new Vector3(-10,.15f,47),new Vector3(-2,.15f,48),new Vector3(0,.15f,55),new Vector3(0,.15f,75),new Vector3(5,.15f,95),new Vector3(18,.15f,115),new Vector3(33,.15f,133),new Vector3(48,.15f,145),new Vector3(64,.15f,153)};
m.road.points=pts.Select((p,i)=>At("호송 경유 "+i,routeRoot,p)).ToArray();m.start.SetPositionAndRotation(pts[0],m.road.Rotation(0));m.vehicle.SetPositionAndRotation(m.start.position,m.start.rotation);m.destination.SetPositionAndRotation(pts[pts.Length-1],m.road.Rotation(1));m.rideSeconds=55;
m.playerExit.SetPositionAndRotation(new Vector3(59,.08f,158),Quaternion.Euler(0,130,0));m.friendExit.SetPositionAndRotation(new Vector3(61,.08f,157),Quaternion.Euler(0,-50,0));
m.previous.vehiclePoint.position=new Vector3(-46,.15f,-20);m.previous.previous.legacyEscape.boardingPoint.position=m.previous.vehiclePoint.position;
m.gateShot=At("정문 개방 컷씬",root,new Vector3(9,4,63));m.gateShot.LookAt(new Vector3(0,1.3f,48));
// Keep the covert approach along real passages, away from the vehicle lane.
m.previous.checkpoint.position=new Vector3(-20,0,22);m.previous.companionStart.position=new Vector3(-21.5f,0,22);
var sneak=new[]{new Vector3(-32,0,23),new Vector3(-46,0,20),new Vector3(-46,0,-5)};for(int i=0;i<m.previous.route.Length;i++)m.previous.route[i].position=sneak[Mathf.Min(i,2)];
var cover=new[]{new Vector3(-30,0,25),new Vector3(-44.8f,0,19),new Vector3(-45,0,1)};for(int i=0;i<m.previous.coverProps.transform.childCount;i++)m.previous.coverProps.transform.GetChild(i).position=cover[Mathf.Min(i,2)];
m.previous.establishingShot.position=new Vector3(-40,5,19);m.previous.establishingShot.LookAt(new Vector3(-48,0,-12));
m.previous.searchlights[0].sweepFrom=new Vector3(-40,0,22);m.previous.searchlights[0].sweepTo=new Vector3(-22,0,25);m.previous.searchlights[1].transform.position=new Vector3(-54,11,-34);m.previous.searchlights[1].sweepFrom=new Vector3(-48,0,-14);m.previous.searchlights[1].sweepTo=new Vector3(-48,0,15);
var grass=Mat("외곽 잔디",new Color(.24f,.32f,.18f));var asphalt=Mat("호송 도로",new Color(.12f,.14f,.15f));var shoulder=Mat("흙길 가장자리",new Color(.37f,.34f,.25f));var stripe=Mat("도로 표식",new Color(.78f,.73f,.52f));
var ground=At("외부 보행 지면",root,Vector3.zero);Box("숲길 지면",ground,new Vector3(0,-.15f,155),new Vector3(280,.3f,200),grass);
var roadRoot=At("외곽 아스팔트와 갓길",root,Vector3.zero);
// A continuous sampled ribbon prevents gaps between curved road pieces.
Ribbon(m.road,roadRoot,"차도",.0f,8,asphalt);Ribbon(m.road,roadRoot,"갓길",-.015f,11,shoulder);
for(float t=.0f;t<1;t+=5/m.road.Length){var p=m.road.Position(t);if(p.z<55)continue;var mark=Box("중앙 점선",roadRoot,new Vector3(p.x,.016f,p.z),new Vector3(.12f,.012f,2),stripe);mark.transform.rotation=m.road.Rotation(t);Object.DestroyImmediate(mark.GetComponent<Collider>());}
var nature=At("도로 주변 Synty 산림",root,Vector3.zero);var random=new System.Random(1911);
for(int i=0;i<95;i++){float z=60+(float)random.NextDouble()*130;float x=-92+(float)random.NextDouble()*205;var p=new Vector3(x,0,z);if(Distance(m.road,p)<12)continue;Prop("SM_Gen_Env_Tree_Pine_0"+(1+i%3),nature,p,6+(float)random.NextDouble()*7,(float)random.NextDouble()*360);}
for(int i=0;i<150;i++){float t=(float)random.NextDouble();var p=m.road.Position(t);if(p.z<56)continue;p+=m.road.Rotation(t)*Vector3.right*(i%2==0?1:-1)*(6+(float)random.NextDouble()*6);p.y=.01f;Prop("SM_Gen_Env_Grass_0"+(1+i%7),nature,p,.25f+(float)random.NextDouble()*.45f,i*67);}
foreach(var p in new[]{new Vector3(-42,0,85),new Vector3(-38,0,140),new Vector3(65,0,86),new Vector3(90,0,115),new Vector3(4,0,180),new Vector3(118,0,177)})Prop("SM_Gen_Env_Mountain_02",nature,p,18,random.Next(360));
for(int i=0;i<20;i++){var p=m.road.Position(.5f+i*.025f);p+=m.road.Rotation(.5f+i*.025f)*Vector3.right*(i%2==0?10:-10);p.y=0;Prop("SM_Gen_Env_Rock_0"+(1+i%3),nature,p,1+i%3*.4f,i*41);}
// Independent exterior navigation leaves the existing prison bake untouched.
var nav=ground.gameObject.AddComponent<NavMeshSurface>();nav.collectObjects=CollectObjects.Children;nav.useGeometry=UnityEngine.AI.NavMeshCollectGeometry.PhysicsColliders;nav.BuildNavMesh();AssetDatabase.CreateAsset(nav.navMeshData,Folder+"외곽 보행 NavMesh.asset");
Physics.SyncTransforms();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
File.WriteAllText("Logs/Prison-exterior-build.txt","PASS saved. route length="+m.road.Length+" ride="+m.rideSeconds+" start="+m.start.position+" end="+m.destination.position);
Survey();}
static float Distance(PrisonTransportRoute route,Vector3 p){float d=9999;for(float t=0;t<=1;t+=.01f)d=Mathf.Min(d,Vector3.Distance(p,route.Position(t)));return d;}
static void Ribbon(PrisonTransportRoute route,Transform root,string name,float y,float width,Material mat){var vertices=new System.Collections.Generic.List<Vector3>();var triangles=new System.Collections.Generic.List<int>();int count=Mathf.CeilToInt(route.Length);for(int i=0;i<=count;i++){float t=i/(float)count;var p=route.Position(t);p.y=y;var side=route.Rotation(t)*Vector3.right*width*.5f;vertices.Add(p-side);vertices.Add(p+side);if(i==0)continue;int j=i*2;triangles.AddRange(new[]{j-2,j,j-1,j-1,j,j+1});}var mesh=new Mesh();mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,Folder+name+".asset");var go=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer),typeof(MeshCollider));go.transform.SetParent(root,false);go.GetComponent<MeshFilter>().sharedMesh=mesh;go.GetComponent<MeshRenderer>().sharedMaterial=mat;go.GetComponent<MeshCollider>().sharedMesh=mesh;go.isStatic=true;}
static void Polish(){var m=Object.FindFirstObjectByType<PrisonTransportEscape>();var scene=m.gameObject.scene;EditorSceneManager.SaveScene(scene,"Logs/Prison-before-exterior-polish.unity",true);
var ground=m.road.transform.parent.Find("외부 보행 지면/숲길 지면").gameObject;ground.transform.position=new Vector3(0,-.19f,155);
m.previous.curfewActors=Object.FindObjectsByType<NPCControl>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(n=>n.transform!=m.Friend.transform&&n.transform!=m.Player.transform).Select(n=>n.gameObject).ToArray();
if(!m.road.transform.parent.Find("이어지는 산길")){var tail=At("이어지는 산길",m.road.transform.parent,Vector3.zero);var rr=tail.gameObject.AddComponent<PrisonTransportRoute>();rr.points=new[]{At("연장 시작",tail,m.destination.position),At("숲길 직선",tail,m.destination.position+m.destination.forward*28),At("산 뒤로 꺾이는 도로",tail,new Vector3(111,.15f,177)),At("먼 도로 끝",tail,new Vector3(115,.15f,205))};Ribbon(rr,tail,"연장 차도",0,8,Mat("호송 도로",new Color(.12f,.14f,.15f)));Ribbon(rr,tail,"연장 갓길",-.015f,11,Mat("흙길 가장자리",new Color(.37f,.34f,.25f)));}
AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Survey();}
static void Approach(){var m=Object.FindFirstObjectByType<PrisonTransportEscape>();var scene=m.gameObject.scene;EditorSceneManager.SaveScene(scene,"Logs/Prison-before-van-approach.unity",true);m.previous.vehiclePoint.position=new Vector3(-45.4f,.15f,-20);m.previous.previous.legacyEscape.boardingPoint.position=m.previous.vehiclePoint.position;var obstacle=m.vehicle.GetComponent<UnityEngine.AI.NavMeshObstacle>();if(!obstacle)obstacle=m.vehicle.gameObject.AddComponent<UnityEngine.AI.NavMeshObstacle>();obstacle.shape=UnityEngine.AI.NavMeshObstacleShape.Box;obstacle.center=new Vector3(0,1,0);obstacle.size=new Vector3(2.6f,2.4f,5.5f);obstacle.carving=true;obstacle.carveOnlyStationary=true;EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("Logs/Prison-van-approach.txt","PASS boarding beside vehicle; parked vehicle navigation obstacle");}
static void Sweep(){var m=Object.FindFirstObjectByType<PrisonNightMission>();var scene=m.gameObject.scene;EditorSceneManager.SaveScene(scene,"Logs/Prison-before-sweep-polish.unity",true);var light=m.searchlights[1];light.sweepFrom=new Vector3(-55,0,-7);light.sweepTo=new Vector3(-39,0,-7);light.period=16;light.ResetSweep();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("Logs/Prison-sweep-polish.txt","PASS transverse search sweep provides a waiting area before crossing");}
static void Audit(){var m=Object.FindFirstObjectByType<PrisonTransportEscape>();var sb=new System.Text.StringBuilder();var points=new[]{m.previous.checkpoint}.Concat(m.previous.route).Concat(new[]{m.previous.vehiclePoint}).ToArray();for(int i=1;i<points.Length;i++){var path=new UnityEngine.AI.NavMeshPath();bool a=UnityEngine.AI.NavMesh.SamplePosition(points[i-1].position,out var from,3,UnityEngine.AI.NavMesh.AllAreas);bool b=UnityEngine.AI.NavMesh.SamplePosition(points[i].position,out var to,3,UnityEngine.AI.NavMesh.AllAreas);bool ok=a&&b&&UnityEngine.AI.NavMesh.CalculatePath(from.position,to.position,UnityEngine.AI.NavMesh.AllAreas,path)&&path.status==UnityEngine.AI.NavMeshPathStatus.PathComplete;sb.AppendLine((ok?"PASS ":"FAIL ")+"sneak leg "+i);}
var left=Quaternion.identity;var right=Quaternion.identity;m.gateLeft.rotation=left*Quaternion.Euler(0,-100,0);m.gateRight.rotation=right*Quaternion.Euler(0,100,0);Physics.SyncTransforms();bool clear=true;for(float t=0;t<=1;t+=.002f){var p=m.road.Position(t);if(p.z<46||p.z>59)continue;foreach(var c in Physics.OverlapBox(p+Vector3.up*1.25f,new Vector3(.95f,.8f,2.3f),m.road.Rotation(t),~0,QueryTriggerInteraction.Ignore))if(c.transform.IsChildOf(m.gateLeft)||c.transform.IsChildOf(m.gateRight))clear=false;}
sb.AppendLine((clear?"PASS ":"FAIL ")+"open gates clear vehicle envelope");m.gateLeft.rotation=left;m.gateRight.rotation=right;Physics.SyncTransforms();File.WriteAllText("Logs/Prison-exterior-audit.txt",sb.ToString());}
static void Survey(){var m=Object.FindFirstObjectByType<PrisonTransportEscape>();var s="VEHICLE "+m.vehicle.position+" GATE "+m.gateLeft.position+" / "+m.gateRight.position+" END "+m.destination.position+"\n";foreach(var t in Object.FindObjectsByType<Transform>(FindObjectsInactive.Include,FindObjectsSortMode.None))if(t.name.Contains("창고")||t.name.Contains("의무")||t.name.Contains("외곽")||t.name.Contains("산맥"))s+=t.name+" "+t.position+"\n";foreach(var r in Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None))if(r.bounds.size.x>15||r.bounds.size.z>15)s+=r.name+" "+r.bounds+"\n";foreach(var n in Object.FindObjectsByType<NavMeshSurface>(FindObjectsSortMode.None))s+="NAV "+n.name+" "+n.collectObjects+"\n";if(m.road){var hits=new System.Collections.Generic.HashSet<string>();for(float t=0;t<=1;t+=.003f){var p=m.road.Position(t);foreach(var c in Physics.OverlapBox(p+Vector3.up*1.25f,new Vector3(.95f,.8f,2.3f),m.road.Rotation(t),~0,QueryTriggerInteraction.Ignore)){if(c.transform.IsChildOf(m.vehicle)||c.GetComponentInParent<NPCControl>()||c.GetComponentInParent<PlayerCombat>())continue;hits.Add(c.name+" "+c.bounds+" route="+p);}}File.WriteAllText("Logs/Prison-road-clearance.txt",string.Join("\n",hits));}
File.WriteAllText("Logs/Prison-exterior.txt",s);var go=new GameObject("survey");var cam=go.AddComponent<Camera>();cam.cullingMask=m.film.cullingMask;cam.transform.position=new Vector3(80,125,85);cam.transform.LookAt(new Vector3(0,0,15));cam.farClipPlane=600;var maps=Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None).Where(r=>r.name.Contains("Navigation Map")&&r.enabled).ToArray();foreach(var r in maps)r.enabled=false;
PrisonChickenCheck.Capture(cam,"Logs/Prison-exterior-overview.png");cam.transform.position=new Vector3(7,3,65);cam.transform.LookAt(new Vector3(0,1,49));PrisonChickenCheck.Capture(cam,"Logs/Prison-exterior-gate.png");cam.transform.position=new Vector3(40,2,142);cam.transform.LookAt(new Vector3(60,1,152));PrisonChickenCheck.Capture(cam,"Logs/Prison-exterior-road.png");foreach(var r in maps)r.enabled=true;Object.DestroyImmediate(go);}
